/**
 * File: fixtures.ts
 * Purpose: Bundled SAGE seed / mutation / quarantine fixture corpus.
 *
 * Story: WAVE2-SAGE / ADR-0014, expanded in WAVE7B.5 / ADR-0063
 *  (seed 15 -> 100 across 8 -> 20 categories, mutation 9 -> 30,
 *  quarantine 12 -> 60, criticity field, BU branding).
 *
 * The quarantine corpus includes intentionally-malicious strings (SQL
 * injection, XSS, SSRF, JWT leak, LFI, RCE, ANSI escapes, zero-width
 * payloads, homoglyphs). They are stored as data and only ever
 * rendered through `SafeCodeBlock`.
 */

export const SAGE_CRITICITY_LEVELS = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO'] as const
export type SageCriticity = (typeof SAGE_CRITICITY_LEVELS)[number]

export const SEED_CATEGORIES = [
  // Wave 2 baseline
  'injection',
  'jailbreak',
  'extraction',
  'encoding',
  'social',
  'multi-turn',
  'system-prompt',
  'tool-abuse',
  // Wave 7B.5 additions (2026-vintage attack patterns)
  'indirect-injection',
  'ansi-escape',
  'zero-width',
  'homoglyph',
  'markdown-injection',
  'agentic-loop',
  'memory-poisoning',
  'context-overflow',
  'pii-extraction',
  'cost-amplification',
  'compliance-bypass',
  'multi-modal',
] as const

export type SeedCategory = (typeof SEED_CATEGORIES)[number]

export interface SeedRecord {
  id: string
  name: string
  category: SeedCategory
  content: string
  description: string
  fitness: number
  usageCount: number
  successRate: number
  generation: number
  createdAt: string
  tags: string[]
  criticity: SageCriticity
}

export interface MutationExampleRecord {
  before: string
  after: string
  explanation: string
}

export const MUTATION_CATEGORIES = [
  'substitution',
  'insertion',
  'deletion',
  'encoding',
  'structural',
  'semantic',
] as const

export type MutationCategory = (typeof MUTATION_CATEGORIES)[number]

export interface MutationOperatorRecord {
  id: string
  name: string
  category: MutationCategory
  description: string
  weight: number
  hitCount: number
  successRate: number
  examples: MutationExampleRecord[]
  avgFitnessGain: number
  createdAt: string
  criticity: SageCriticity
}

export interface QuarantineRecord {
  id: string
  content: string
  reason: string
  status: 'pending' | 'approved' | 'rejected'
  submittedAt: string
  reviewedAt: string | null
  reviewerNotes: string | null
  category: string | null
  generation: number
  fitness: number
  criticity: SageCriticity
}

